export type AppLanguage = "pl" | "en" | "de" | "nl" | "es";

export type TranslationRow = Record<AppLanguage, string>;

export const languages: Array<{ code: AppLanguage; short: string; label: string; locale: string }> = [
  { code: "pl", short: "PL", label: "Polski", locale: "pl-PL" },
  { code: "en", short: "EN", label: "English", locale: "en-GB" },
  { code: "de", short: "DE", label: "Deutsch", locale: "de-DE" },
  { code: "nl", short: "NL", label: "Nederlands", locale: "nl-NL" },
  { code: "es", short: "ES", label: "Español", locale: "es-ES" },
];

function row(pl: string, en: string, de: string, nl: string, es: string): TranslationRow {
  return { pl, en, de, nl, es };
}

function normalizePhrase(value: string) {
  return value.trim().replace(/\s+/g, " ").toLocaleLowerCase();
}

