export function translateExact(text: string, target: AppLanguage): string | null {
  const normalized = normalizePhrase(text);
  if (!normalized) return text;

  for (const lang of Object.keys(phraseIndex) as AppLanguage[]) {
    const item = phraseIndex[lang].get(normalized);
    if (item) return item[target];
  }

  const numberedLesson = text.trim().match(/^(\d+)\.\s+(.+)$/);
  if (numberedLesson) {
    const [, number, label] = numberedLesson;
    const translated = translateExact(label, target);
    if (translated) return `${number}. ${translated}`;
  }

  const module = text.trim().match(/^Modu(?:ł|Å‚)\s+(\d+)\s*[–-]\s*(.+)$/i);
  if (module) {
    const [, number, label] = module;
    const prefix = target === "de" ? "Modul" : target === "nl" ? "Module" : target === "es" ? "Módulo" : target === "en" ? "Module" : "Moduł";
    return `${prefix} ${number} – ${label}`;
  }

  const materials = text.trim().match(/^(\d+)(?:\s*\/\s*(\d+))?\s+materiał(?:ów|y)?$/i);
  if (materials) {
    const [, a, b] = materials;
    const n = b ? `${a} / ${b}` : a;
    const word = target === "de" ? "Materialien" : target === "nl" ? "materialen" : target === "es" ? "materiales" : target === "en" ? "materials" : "materiałów";
    return `${n} ${word}`;
  }

  const files = text.trim().match(/^(\d+)\s+plików$/i);
  if (files) {
    const word = target === "de" ? "Dateien" : target === "nl" ? "bestanden" : target === "es" ? "archivos" : target === "en" ? "files" : "plików";
    return `${files[1]} ${word}`;
  }

  return null;
}
